// Repertório: cifras e lista de músicas (somente dados).

const KEYS = ['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B',
              'Am','Bm','Cm','Dm','Em','Fm','Gm'];

function mkC(key) {
  const T = {
    'C':['C','G','Am','F'],'D':['D','A','Bm','G'],'E':['E','B','C#m','A'],
    'F':['F','C','Dm','Bb'],'G':['G','D','Em','C'],'A':['A','E','F#m','D'],
    'B':['B','F#','G#m','E'],'Bb':['Bb','F','Gm','Eb'],'Eb':['Eb','Bb','Cm','Ab'],
    'Am':['Am','G','F','E7'],'Dm':['Dm','C','Bb','A7'],'Em':['Em','D','C','B7'],
    'Bm':['Bm','A','G','F#7'],'C#':['C#','G#','A#m','F#'],'F#':['F#','C#','D#m','B'],
    'Ab':['Ab','Eb','Fm','Db'],'Gm':['Gm','F','Eb','D7'],'Fm':['Fm','C7','Bb','Db'],
    'Cm':['Cm','G7','Ab','Eb']
  };
  const [I,V,vi,IV] = T[key]||T['G'];
  const p=(s,n=16)=>s.padEnd(n);
  return `[Intro]\n${I}  ${V}  ${vi}  ${IV}\n\n[Verso 1]\n${p(I)}${V}\nPrimeira linha da letra da música\n${p(vi)}${IV}\nSegunda linha da letra continua\n\n[Pré-Refrão]\n${p(IV)}${V}\nLinha de transição para o refrão\n\n[Refrão]\n${p(I)}${V}\nRefrão primeira linha aqui\n${p(vi)}${IV}\nRefrão segunda linha aqui\n${p(I)}${p(IV)}\nFinal do refrão aqui\n\n[Verso 2]\n${p(I)}${V}\nTerceira estrofe da música\n${p(vi)}${IV}\nQuarta linha da letra aqui\n\n[Refrão]\n${p(I)}${V}\nRefrão primeira linha aqui\n${p(vi)}${IV}\nRefrão segunda linha aqui\n${p(I)}${p(IV)}\nFinal do refrão aqui\n\n[Final]\n${I}  ${IV}  ${I}`;
}

